toolScript:
let audioContext;
        let analyser;
        let microphone;
        let isRunning = false;
        let isLoopback = false;
        let canvas, ctx;
        let animationId;
        // --- 1. Canvas Logic (Enhanced for Dopamine) ---
        window.addEventListener('load', () => {
            canvas = document.getElementById('waveform-canvas');
            ctx = canvas.getContext('2d');
            resizeCanvas();
            window.addEventListener('resize', resizeCanvas);
            drawSilentWaveform();
            // Tutorial Check
            const tutDone = localStorage.getItem('mic_latency_tut_done');
            if (!tutDone) {
                setTimeout(() => startTutorial(false), 1000);
            }
        });
        function resizeCanvas() {
            canvas.width = canvas.parentElement.offsetWidth;
            canvas.height = canvas.parentElement.offsetHeight;
        }
        // --- 2. Audio Engine (With Suspense Logic) ---
        async function startAudioEngine() {
            if (isRunning) return;
            // End tutorial if active
            if (tutorialStep > 0) endTutorial();
            try {
                audioContext = new (window.AudioContext || window.webkitAudioContext)({
                    latencyHint: 'interactive'
                });
                // Display System Latency Logic (Enhanced Calculation with Delay)
                const outputLat = audioContext.outputLatency || 0;
                const baseLat = audioContext.baseLatency || 0;
                const estimatedTotal = (outputLat + baseLat) * 1000;
                // Suspense Phase: Scramble numbers before settling
                document.getElementById('latency-val').innerHTML = '<span class="text-3xl text-slate-400 animate-pulse">CALCULATING...</span>';
                // Get Mic Stream
                const stream = await navigator.mediaDevices.getUserMedia({
                    audio: {
                        echoCancellation: false,
                        noiseSuppression: false,
                        autoGainControl: false,
                        latency: 0
                    }
                });
                microphone = audioContext.createMediaStreamSource(stream);
                analyser = audioContext.createAnalyser();
                analyser.fftSize = 2048;
                analyser.smoothingTimeConstant = 0.8; // Smoother visual
                microphone.connect(analyser);
                // UI Updates (Immediate)
                document.getElementById('status-light').classList.remove('bg-red-500');
                document.getElementById('status-light').classList.add('bg-emerald-500', 'animate-pulse');
                document.getElementById('mic-status').innerText = "DRIVER ACTIVE (48kHz)";
                document.getElementById('start-btn').innerHTML = `<span class="relative z-10 flex items-center gap-3"><div class="w-3 h-3 bg-white rounded-full animate-ping"></div><span>SENSOR ACTIVE</span></span>`;
                document.getElementById('start-btn').classList.add('bg-emerald-600');
                document.getElementById('loop-btn').disabled = false;
                isRunning = true;
                visualize();
                // Reveal Result after "Simulation" Delay (Psychological Hook)
                setTimeout(() => {
                    const finalVal = Math.max(12, Math.round(estimatedTotal));
                    animateValue("latency-val", 0, finalVal, 1500);
                    showRank(finalVal); // Trigger Rank Display
                    if (estimatedTotal > 0) {
                        document.getElementById('driver-stats').classList.remove('hidden');
                        document.getElementById('output-latency-val').innerText = (outputLat * 1000).toFixed(2);
                    }
                }, 1200);
            } catch (err) {
                alert("Microphone access denied or not found. Please allow permission to use the tool.");
                console.error(err);
            }
        }
        function toggleLoopback() {
            if (!isRunning) return;
            if (!isLoopback) {
                // Connect to destination (Loopback)
                microphone.connect(audioContext.destination);
                isLoopback = true;
                document.getElementById('loop-btn').classList.remove('bg-slate-900');
                document.getElementById('loop-btn').classList.add('bg-red-600', 'animate-pulse');
                document.getElementById('loop-btn').innerHTML = '<span><svg class="w-4 h-4 inline-block text-amber-500" fill="none" stroke="currentColor" viewBox="0 0 24 24" aria-hidden="true"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z"/></svg> STOP LOOPBACK</span>';
            } else {
                // Disconnect
                microphone.disconnect(audioContext.destination);
                microphone.connect(analyser); // Reconnect to analyser only
                isLoopback = false;
                document.getElementById('loop-btn').classList.add('bg-slate-900');
                document.getElementById('loop-btn').classList.remove('bg-red-600', 'animate-pulse');
                document.getElementById('loop-btn').innerHTML = "<span>TEST LOOPBACK (HEADPHONES ONLY)</span>";
            }
        }
        // --- 3. Enhanced Visualization (Neon Style) ---
        function visualize() {
            const bufferLength = analyser.frequencyBinCount;
            const dataArray = new Uint8Array(bufferLength);
            const draw = () => {
                animationId = requestAnimationFrame(draw);
                analyser.getByteTimeDomainData(dataArray);
                // Fading trail effect
                ctx.fillStyle = 'rgba(2, 6, 23, 0.2)';
                ctx.fillRect(0, 0, canvas.width, canvas.height);
                ctx.lineWidth = 3;
                // Gradient Line
                const gradient = ctx.createLinearGradient(0, 0, canvas.width, 0);
                gradient.addColorStop(0, '#38bdf8');
                gradient.addColorStop(1, '#818cf8');
                ctx.strokeStyle = gradient;
                ctx.beginPath();
                const sliceWidth = canvas.width * 1.0 / bufferLength;
                let x = 0;
                for (let i = 0; i < bufferLength; i++) {
                    const v = dataArray[i] / 128.0;
                    const y = v * canvas.height / 2;
                    if (i === 0) ctx.moveTo(x, y);
                    else ctx.lineTo(x, y);
                    x += sliceWidth;
                }
                ctx.lineTo(canvas.width, canvas.height / 2);
                ctx.stroke();
            };
            draw();
        }
        function drawSilentWaveform() {
            ctx.fillStyle = '#020617';
            ctx.fillRect(0, 0, canvas.width, canvas.height);
            ctx.beginPath();
            ctx.moveTo(0, canvas.height / 2);
            ctx.lineTo(canvas.width, canvas.height / 2);
            ctx.strokeStyle = '#1e293b';
            ctx.lineWidth = 1;
            ctx.stroke();
        }
        function animateValue(id, start, end, duration) {
            if (start === end) return;
            const range = end - start;
            let current = start;
            const increment = end > start ? 1 : -1;
            const stepTime = Math.abs(Math.floor(duration / range));
            const obj = document.getElementById(id);
            const timer = setInterval(function () {
                current += increment;
                obj.innerHTML = current + '<span class="ms-unit">ms</span>';
                if (current == end) {
                    clearInterval(timer);
                }
            }, stepTime);
        }
        // --- 4. Gamification Logic (Ranks & Badges) ---
        function showRank(latency) {
            const badge = document.getElementById('rank-badge');
            const txt = document.getElementById('rank-text');
            const confettiBox = document.getElementById('confetti-container');
            badge.className = "rank-badge rank-visible";
            if (latency < 15) {
                badge.classList.add('rank-s');
                txt.innerText = "S-RANK: STUDIO GRADE";
                createConfetti(confettiBox); // Trigger Dopamine Confetti
            } else if (latency < 30) {
                badge.classList.add('rank-a');
                txt.innerText = "A-RANK: GAMING READY";
            } else if (latency < 60) {
                badge.classList.add('rank-b');
                txt.innerText = "B-RANK: ACCEPTABLE";
            } else if (latency < 100) {
                badge.classList.add('rank-c');
                txt.innerText = "C-RANK: NOTICEABLE LAG";
            } else {
                badge.classList.add('rank-f');
                txt.innerText = "F-RANK: CRITICAL FAILURE";
            }
            badge.classList.remove('hidden');
        }
        function createConfetti(container) {
            const colors = ['#f00', '#0f0', '#00f', '#ff0', '#0ff', '#f0f'];
            for (let i = 0; i < 50; i++) {
                const conf = document.createElement('div');
                conf.classList.add('confetti');
                conf.style.left = Math.random() * 100 + '%';
                conf.style.backgroundColor = colors[Math.floor(Math.random() * colors.length)];
                conf.style.animationDuration = (Math.random() * 2 + 1) + 's';
                container.appendChild(conf);
                // Cleanup
                setTimeout(() => conf.remove(), 3000);
            }
        }
        // --- 5. Interactive Tutorial Engine ---
        let tutorialStep = 0;
        const steps = [
            { el: 'start-btn', title: 'Start Here', text: 'Click this button to initialize the audio engine. We need browser permission to access the timing clock.' },
            { el: 'target-visualizer', title: 'Verify Input', text: 'Once active, this graph will react to your voice. If it is flat, your mic is muted.' },
            { el: 'loop-btn', title: 'The Loopback Test', text: 'Use headphones! Click here to hear yourself. The delay you hear is your Round Trip Latency.' }
        ];
        function startTutorial(force) {
            if (!force && localStorage.getItem('mic_latency_tut_done')) return;
            document.body.classList.add('tutorial-active');
            tutorialStep = 0;
            showStep();
        }
        function showStep() {
            if (tutorialStep >= steps.length) {
                endTutorial();
                return;
            }
            const step = steps[tutorialStep];
            const el = document.getElementById(step.el);
            const tooltip = document.getElementById('tutorial-tooltip');
            // Highlight Element
            document.querySelectorAll('.tutorial-highlight').forEach(e => e.classList.remove('tutorial-highlight'));
            el.classList.add('tutorial-highlight');
            // Position Tooltip
            const rect = el.getBoundingClientRect();
            const tipRect = tooltip.getBoundingClientRect();
            // Basic logic to place tooltip below or above
            let top = rect.bottom + 15;
            let left = rect.left + (rect.width / 2) - (tipRect.width / 2);
            // Adjust for mobile edges
            if (left < 10) left = 10;
            tooltip.style.top = `${top + window.scrollY}px`;
            tooltip.style.left = `${left}px`;
            // Update Content
            document.getElementById('tut-title').innerText = step.title;
            document.getElementById('tut-text').innerText = step.text;
            document.getElementById('tut-step').innerText = `${tutorialStep + 1}/${steps.length}`;
            tooltip.classList.add('visible');
        }
        function nextTutorialStep() {
            tutorialStep++;
            showStep();
        }
        function endTutorial() {
            document.body.classList.remove('tutorial-active');
            document.querySelectorAll('.tutorial-highlight').forEach(e => e.classList.remove('tutorial-highlight'));
            document.getElementById('tutorial-tooltip').classList.remove('visible');
            localStorage.setItem('mic_latency_tut_done', 'true');
            tutorialStep = 0;
        }
        // Scroll Logic (Kept from Original)
